// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.utilimport timber.log.Timberimport android.content.Contextimport android.hardware.camera2.CameraAccessExceptionimport android.os.PowerManagerimport android.provider.Settingsimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Result/** * NOUS — Hardware Exception Mapper (Module 10 v2 — Review 2 Fix C). * * Maps Android hardware exceptions to typed [AppError.Hardware] subtypes so * the Brain can show user-friendly messages instead of crashing. Every * handler wraps its Android API call in try-catch and delegates to this * mapper. * * ## Mapped exception types * * | Exception | AppError | User message | * |-----------|----------|--------------| * | `CameraAccessException(CAMERA_IN_USE)` | `Hardware.InUse("camera")` | "Camera is in use by another app" | * | `CameraAccessException(MAX_CAMERAS_IN_USE)` | `Hardware.InUse("camera")` | "Camera limit reached" | * | `CameraAccessException(CAMERA_DISCONNECTED)` | `Hardware.Unavailable("camera")` | "Camera disconnected" | * | `SecurityException` | `Permission.Denied` | "Need permission" | * | `UnsupportedOperationException` | `Hardware.Unsupported(resource)` | "Not supported" | * | `IllegalArgumentException` | `Hardware.Unsupported(resource)` | "Not supported by carrier/OEM" | * | `ActivityNotFoundException` | `Hardware.Unsupported(resource)` | "No app to handle this" | * | Other | `Hardware.Unknown(resource)` | "Unknown hardware error" | * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Privacy & Security — Hardware Exception Matrix</a> */object HardwareExceptionMapper {    /**     * Map a thrown exception to an [AppError.Hardware] subtype.     *     * @param resource  the hardware resource name (e.g., "camera", "torch", "wifi").     * @param throwable the thrown exception.     * @return typed [AppError.Hardware] for the Brain to display.     */    fun map(resource: String, throwable: Throwable): AppError.Hardware {        return when (throwable) {            // Camera exceptions — torch handler.            is CameraAccessException -> when (throwable.reason) {                CameraAccessException.CAMERA_IN_USE ->                    AppError.Hardware.InUse(resource, throwable)                CameraAccessException.MAX_CAMERAS_IN_USE ->                    AppError.Hardware.InUse(resource, throwable)                CameraAccessException.CAMERA_DISCONNECTED,                CameraAccessException.CAMERA_DISABLED,                CameraAccessException.CAMERA_ERROR ->                    AppError.Hardware.Unavailable(resource, throwable)                else -> AppError.Hardware.Unknown(resource, throwable)            }            // NFC — NfcAdapter.enable() throws this on non-NFC devices.            is UnsupportedOperationException ->                AppError.Hardware.Unsupported(resource, throwable)            // Tethering — startTethering throws this when carrier blocks.            is IllegalArgumentException ->                AppError.Hardware.Unsupported(resource, throwable)            // No app to handle AlarmClock intent (rare — every Android ships a clock).            is android.content.ActivityNotFoundException ->                AppError.Hardware.Unsupported(resource, throwable)            // Catch-all — preserve the cause for debugging.            else -> AppError.Hardware.Unknown(resource, throwable)        }    }    /**     * Wrap a suspending block, mapping any thrown exception to a [Result.Failure].     *     * Usage in handlers:     * ```kotlin     * override suspend fun execute(op: SetTorch): Result<Unit> =     *     HardwareExceptionMapper.withMapping("torch") {     *         cameraManager.setTorchMode(cameraId, op.on)     *         Result.Success(Unit, CorrelationId.generate(), 0)     *     }     * ```     */    suspend fun <T> withMapping(        resource: String,        block: suspend () -> Result<T>,    ): Result<T> {        return try {            block()        } catch (t: Throwable) {            Result.Failure(                error = map(resource, t),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }    }    /**     * Wrap a synchronous block, mapping any thrown exception to a [Result.Failure].     */    fun <T> withMappingSync(        resource: String,        block: () -> Result<T>,    ): Result<T> {        return try {            block()        } catch (t: Throwable) {            Result.Failure(                error = map(resource, t),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }    }}// ──────────────────────────────────────────────────────────────────────────/** * NOUS — Settings Helper (Module 10 v2). * * Wraps Android `Settings.Secure` / `Settings.Global` write capability checks. * Many system operations (Location mode, NFC, Airplane Mode) can only be * toggled programmatically by system apps or apps with `WRITE_SECURE_SETTINGS` * granted via ADB. Regular apps must fall back to opening the Settings page. * * ## Usage * * ```kotlin * if (settingsHelper.canWriteSecureSettings()) { *     // Direct toggle (system app / rooted / ADB-granted) *     Settings.Global.putInt(...) * } else { *     // Fallback: open Settings page for user to toggle manually *     context.startActivity(Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS)) * } * ``` */class SettingsHelper(private val context: Context) {    /**     * True if this app can write to `Settings.Secure` / `Settings.Global`.     *     * Requires `WRITE_SECURE_SETTINGS` permission — granted via:     *  - System app installation (OEM-signed).     *  - ADB: `adb shell pm grant com.roshan.persona android.permission.WRITE_SECURE_SETTINGS`.     *  - Root (Magisk module).     *     * Regular Play Store installs do NOT have this — handlers must fall back     * to opening the Settings page.     */    fun canWriteSecureSettings(): Boolean {        return android.content.pm.PackageManager.PERMISSION_GRANTED ==            context.checkPermission(                android.Manifest.permission.WRITE_SECURE_SETTINGS,                android.os.Process.myPid(),                android.os.Process.myUid(),            )    }    /**     * True if this app can draw over other apps (for system overlays).     *     * Required by some handlers (e.g., keep-screen-on via window flags).     */    fun canDrawOverlays(): Boolean = android.provider.Settings.canDrawOverlays(context)    /**     * Open a Settings page by action string.     *     * Used as fallback when direct toggle isn't possible.     */    fun openSettingsPage(action: String): Result<Unit> {        return try {            val intent = android.content.Intent(action).apply {                addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK)            }            context.startActivity(intent)            Result.Success(Unit, CorrelationId.generate(), 0)        } catch (t: Throwable) {            Result.Failure(                error = AppError.Hardware.Unsupported("settings:$action", t),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }    }}// ──────────────────────────────────────────────────────────────────────────/** * NOUS — Thermal Gate (Module 10 v2 — Review 2 Elite 2). * * Checks device thermal state before allowing hardware-heavy operations * (torch, brightness, camera, hotspot). When the device is thermally * throttled, these operations are refused with a user-friendly message * instead of contributing to further heat. * * ## Thermal headroom semantics (Android PowerManager) * * `getThermalHeadroom()` returns a float: *  - < 1.0  → device is cool, no throttling *  - 1.0–2.0 → moderate throttling, performance reduced *  - 2.0–3.0 → severe throttling, hardware may refuse *  - > 3.0  → critical, shutdown imminent * * Thresholds per strategy v2: *  - `THERMAL_MODERATE` (1.5) — allow but warn. *  - `THERMAL_SEVERE` (2.5) — refuse hardware-heavy ops. * * ## Testability * * Wraps [PowerManager] behind an interface — tests inject a fake that * returns a canned headroom. */class ThermalGate(    private val powerManager: PowerManager?,) {    /**     * Whether the operation should be allowed given the current thermal state.     *     * Per spec (audit defect D / ThermalGate): block torch + max-brightness at     * `THERMAL_MODERATE` (1.5), everything else at `THERMAL_SEVERE` (2.5).     *     * Camera torch + display backlight are the two heaviest heat contributors —     * they push the device into severe throttle quickly and contribute to     * thermal shutdown risk. Blocking them at MODERATE (before severe hits)     * prevents cascading throttle.     *     * Other hardware-heavy operations (tethering, NFC) are less heat-sensitive     * and only blocked at SEVERE.     *     * @param operation       the operation about to execute (must be hardware-heavy).     * @param thermalHeadroom current thermal headroom from [getThermalHeadroom].     * @return `true` if execution should proceed, `false` to refuse + emit     *         [thermalFailure] with a "device is hot, please cool down" advice.     */    fun shouldAllowOperation(        operation: com.roshan.persona.brain.skill.SystemOperation,        thermalHeadroom: Float,    ): Boolean {        // Block torch + max-brightness at MODERATE — they're the heaviest heat sources.        val isHighHeatOperation = when (operation) {            is com.roshan.persona.brain.skill.SystemOperation.SetTorch -> true            is com.roshan.persona.brain.skill.SystemOperation.SetDisplayBrightness -> {                // "Max brightness" = level >= 0.8 — high enough to cause significant heat.                operation.level >= 0.8f            }            else -> false        }        val threshold = if (isHighHeatOperation) THERMAL_MODERATE else THERMAL_SEVERE        return thermalHeadroom < threshold    }    /**     * Legacy overload — looks up headroom internally.     *     * @param operation the operation about to execute.     * @return `true` if execution should proceed, `false` to refuse.     */    fun shouldAllowOperation(operation: HardwareHeavyOperation): Boolean {        val headroom = getThermalHeadroom() ?: return true  // API unavailable → allow        // HardwareHeavyOperation is a marker interface (no operation-type info),        // so we can only apply the SEVERE threshold here. Callers that know the        // concrete SystemOperation type should use the typed overload above.        return headroom < THERMAL_SEVERE    }    /**     * Get the current thermal headroom (0.0–3.0+), or null if unavailable.     *     * `PowerManager.getThermalHeadroom()` requires API 29+.     */    fun getThermalHeadroom(): Float? {        if (powerManager == null) return null        return if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.Q) {            try {                getThermalHeadroomViaReflection(powerManager)            } catch (t: Throwable) {                null  // some OEMs throw on unsupported devices            }        } else null    }    /**     * Build a [Result.Failure] for a thermal-throttled operation.     */    fun thermalFailure(headroom: Float): Result.Failure = Result.Failure(        error = AppError.Hardware.ThermalThrottled(headroom),        correlationId = CorrelationId.generate(),        durationNanos = 0,    )    companion object {        /** Moderate throttling — operations allowed but caller may warn. */        const val THERMAL_MODERATE = 1.5f        /** Severe throttling — hardware-heavy operations refused. */        const val THERMAL_SEVERE = 2.5f    }    /**     * Get thermal headroom via reflection.     *     * `PowerManager.getThermalHeadroom()` is a hidden API (not in public SDK).     * Use reflection to access it at runtime.     */    private fun getThermalHeadroomViaReflection(pm: android.os.PowerManager): Float? {        return try {            val method = pm.javaClass.getMethod("getThermalHeadroom")            method.invoke(pm) as? Float        } catch (e: Throwable) {            Timber.tag("NOUS.System").w("Hardware check failed", e)            null        }    }}// ──────────────────────────────────────────────────────────────────────────/** * Marker for operations that are hardware-heavy (cause heat). * * Used by [ThermalGate] to decide whether to pre-flight check. */interface HardwareHeavyOperation/** * List of operation types considered hardware-heavy per strategy v2. * * Torch (camera flash), brightness (display backlight), hotspot (radio + * CPU), NFC (radio). Other operations (volume, ringer, clipboard, alarms) * are lightweight — no thermal gate needed. */val HARDWARE_HEAVY_OPERATION_TYPES: Set<String> = setOf(    "SetTorch",    "SetDisplayBrightness",    "SetTethering",    "SetNfc",)